scripts.lcg:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(K):
        s = (A * s + B) % M

    return float(s)

scripts.wage_bill:
def solve(inputs: dict) -> float:
    quantities = inputs['QUANTITIES']
    prices = inputs['PRICES']

    total = sum(q * p for q, p in zip(quantities, prices))

    return float(total)

