    result = A * B * C

    return float(result)

scripts.modexp:
def solve(inputs: dict) -> float:
    base = inputs['BASE']
    exp = inputs['EXP']
    mod = inputs['MOD']

    result = pow(base, exp, mod)

    return float(result)

